#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-11-19

# visualize-plan detect-plan-context.sh must count against origin/main, not a
# stale local main (issue #5194). Fixture: a disposable clone whose local main
# lags origin/main by 5 commits, with a feature branch of 2 commits cut from
# the current origin/main. The script must report the branch's own 2 commits
# and 2 added files, never the 5 commits local main is behind.
#
# Cases:
#   1. stale local main, origin/main ahead: Base origin/main, Commits 2, Files 2
#   2. no origin remote: falls back to local main, still correct
#   3. default branch is not main: origin/HEAD names trunk, uses origin/trunk

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
SCRIPT="${DETECT_SCRIPT:-$REPO_ROOT/src/skills/visualize-plan/scripts/detect-plan-context.sh}"

PASS=0
FAIL=0
ok() { echo "  ✓ $1"; PASS=$((PASS + 1)); }
bad() { echo "  ✗ $1"; FAIL=$((FAIL + 1)); }

if [[ ! -f "$SCRIPT" ]]; then
    echo "FAIL: $SCRIPT not found" >&2
    exit 1
fi

TMPDIR="${TMPDIR:-/tmp}"
TMPDIR="${TMPDIR%/}"
export TMPDIR
WORK="$(mktemp -d "$TMPDIR/ork-5194.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT
OUTFILE="$WORK/out.txt"

# Disposable repos: identity and signing are set per commit with -c, so the
# operator's global git config (signer, aliases) is never needed or touched.
# Subcommands are spelled out (no wrapper that hides them). No push anywhere:
# the "remote" is a plain local repo that the clone fetches from.
commit_file() {
    # commit_file <repo> <name>
    echo "$2" > "$1/$2"
    git -C "$1" add "$2"
    git -C "$1" -c user.name=fixture -c user.email=fixture@example.invalid \
        -c commit.gpgsign=false commit -q -m "add $2"
}

# The script under test runs from a copy at a literal $TMPDIR path, so a
# reader (or a guard) can name the file it executes.
cp "$SCRIPT" "$TMPDIR/ork-5194-detect.sh"
trap 'rm -rf "$WORK" "$TMPDIR/ork-5194-detect.sh"' EXIT

run_script() {
    # run_script <repo>: script output lands in $OUTFILE
    (cd "$1" && bash "$TMPDIR/ork-5194-detect.sh" > "$OUTFILE" 2>&1)
}

field() {
    # field <label>: value of the first "<label>: " line in $OUTFILE
    awk -v k="$1: " 'index($0, k) == 1 { print substr($0, length(k) + 1); exit }' "$OUTFILE"
}

# ---- case 1: stale local main, origin/main ahead --------------------------
ORIGIN="$WORK/origin"
CLONE="$WORK/clone"
git init -q -b main "$ORIGIN"
commit_file "$ORIGIN" base1
commit_file "$ORIGIN" base2
git clone -q "$ORIGIN" "$CLONE"
# origin/main moves ahead by 5 commits; the clone's local main stays behind
for n in 1 2 3 4 5; do commit_file "$ORIGIN" "ahead$n"; done
git -C "$CLONE" fetch -q origin
git -C "$CLONE" checkout -q -b feat/thing-5194 origin/main
commit_file "$CLONE" own1
commit_file "$CLONE" own2

run_script "$CLONE"
echo "== case 1: stale local main =="
[[ "$(field Base)" == "origin/main" ]] && ok "base is origin/main" || bad "base: '$(field Base)' (want origin/main)"
[[ "$(field Commits)" == "2" ]] && ok "commits is 2" || bad "commits: '$(field Commits)' (want 2)"
[[ "$(field Files)" == "2 (2 added, 0 modified, 0 deleted)" ]] && ok "files is 2 added" || bad "files: '$(field Files)' (want 2 (2 added, 0 modified, 0 deleted))"
if awk '/ahead[1-5]/ { found = 1 } END { exit !found }' "$OUTFILE"; then
    bad "diff stat lists files that only exist on origin/main"
else
    ok "diff stat excludes origin/main-only files"
fi

# ---- case 2: no origin remote, local main only -----------------------------
SOLO="$WORK/solo"
git init -q -b main "$SOLO"
commit_file "$SOLO" s1
git -C "$SOLO" checkout -q -b feat/solo-7
commit_file "$SOLO" s2
run_script "$SOLO"
echo "== case 2: no remote =="
[[ "$(field Base)" == "main" ]] && ok "base falls back to main" || bad "base: '$(field Base)' (want main)"
[[ "$(field Commits)" == "1" ]] && ok "commits is 1" || bad "commits: '$(field Commits)' (want 1)"

# ---- case 3: default branch is trunk, no origin/main -----------------------
TRUNK_ORIGIN="$WORK/trunk-origin"
TRUNK="$WORK/trunk"
git init -q -b trunk "$TRUNK_ORIGIN"
commit_file "$TRUNK_ORIGIN" t1
git clone -q "$TRUNK_ORIGIN" "$TRUNK"
git -C "$TRUNK" checkout -q -b feat/trunk-9
commit_file "$TRUNK" t2
run_script "$TRUNK"
echo "== case 3: default branch trunk =="
[[ "$(field Base)" == "origin/trunk" ]] && ok "base is origin/HEAD target" || bad "base: '$(field Base)' (want origin/trunk)"
[[ "$(field Commits)" == "1" ]] && ok "commits is 1" || bad "commits: '$(field Commits)' (want 1)"

echo ""
echo "passed: $PASS  failed: $FAIL"
[[ "$FAIL" -eq 0 ]]
